<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';require_login();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$a=(string)($_POST['senha']??'');$b=(string)($_POST['confirmacao']??'');if(strlen($a)<12||$a!==$b)throw new InvalidArgumentException('A senha deve ter 12 caracteres e as confirmações devem coincidir.');$q=$pdo->prepare('UPDATE usuarios SET senha_hash=?,primeiro_acesso=0 WHERE id=?');$q->execute([password_hash($a,PASSWORD_ARGON2ID),current_user()['id']]);audit('ALTERACAO_SENHA','usuarios',current_user()['id']);redirect_authenticated_user();}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'Não foi possível alterar a senha.';}}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com"></script><title>Definir senha | Nexus</title></head><body class="grid min-h-screen place-items-center bg-slate-900 p-5"><form method="post" class="w-full max-w-md rounded-2xl bg-white p-8"><?=csrf_field()?><h1 class="text-2xl font-bold">Defina sua senha</h1><p class="mt-2 text-sm text-slate-500">Por segurança, crie uma senha pessoal antes de continuar.</p><?php if($error):?><p class="mt-4 text-sm text-red-600"><?=e($error)?></p><?php endif;?><input name="senha" type="password" minlength="12" required placeholder="Nova senha" class="mt-6 w-full rounded-lg border p-3"><input name="confirmacao" type="password" minlength="12" required placeholder="Confirme a senha" class="mt-3 w-full rounded-lg border p-3"><button class="mt-5 w-full rounded-lg bg-blue-600 p-3 font-bold text-white">Guardar senha</button></form></body></html>